insert into public.mushroom_lookalikes (edible_slug, lookalike_slug, confusion_risk, key_differences, visual_differences, smell_differences, habitat_differences, spore_print_differences, pro_tip, source) values
($x9$champignon-de-paris$x9$,$x9$agaricus_xanthodermus$x9$,$x9$hoch$x9$,array[$x9$Stielbasis verfaerbt sich beim Anschneiden/Quetschen sofort intensiv chromgelb (leuchtend gelb) – essbare Champignons verfaerben hoechstens schwach gelblich am Hutrand, NIE kraeftig gelb am Stielgrund.$x9$,$x9$Riecht unangenehm nach Karbol/Phenol bzw. Tinte (am besten an der geriebenen Stielbasis oder beim Erhitzen wahrnehmbar) – essbare Champignons riechen pilzig, nussig oder nach Anis/Mandel.$x9$,$x9$Stielbasis zwiebelig verdickt OHNE lappige Haut/Volva; junger Hut oft mit grau-metallischem Schimmer in der Mitte; Lamellen jung rosa, im Alter dunkel schokoladenbraun.$x9$,$x9$Wuchsort identisch (Wiesen, Weiden, Parks, Waldraender, naehrstoffreiche Boeden), daher haeufige reale Verwechslung – der Standort hilft NICHT bei der Unterscheidung.$x9$]::text[],$x9$Karbol-Champignon: Stielbasis verfaerbt sich beim Schnitt sofort chromgelb, Hutmitte oft graulich-metallisch, Stielgrund zwiebelig ohne lappige Haut. Kulturchampignon/Wiesenchampignon: Schnittflaeche bleibt weisslich bis leicht roetlich, kein gelber Stielgrund.$x9$,$x9$Karbol-Champignon riecht stechend nach Karbol/Phenol/Tinte (verstaerkt beim Erhitzen und beim Reiben der Stielbasis). Essbare Champignons riechen angenehm pilzig, nussig oder nach Anis.$x9$,$x9$Beide auf naehrstoffreichen Wiesen, Weiden, in Parks und an Waldraendern, Sommer bis Herbst – Standort hilft NICHT bei der Unterscheidung.$x9$,$x9$Beide schokoladenbraun – Sporenpulverfarbe ist hier KEIN Unterscheidungsmerkmal; auf Gelbverfaerbung und Geruch achten.$x9$,$x9$Stielbasis laengs anschneiden: kraeftig chromgelbes Verfaerben am Stielgrund + Karbol-/Tintengeruch = giftig, Pilz wegwerfen. Nicht oral testen. Folgen sind heftige Magen-Darm-Beschwerden (Uebelkeit, Erbrechen, Durchfall), in der Regel nicht lebensbedrohlich.$x9$,$x9$https://de.wikipedia.org/wiki/Karbol-Champignon · https://www.pilzkurse.com/karbol-champignon/ · https://www.awl.ch/pilze/vergleiche/champignon_vergleich/index.htm$x9$),
($x9$champignon-de-paris$x9$,$x9$gemeiner-fliegenpilz-var-alba$x9$,$x9$sehr_hoch_lebensgefahr$x9$,array[$x9$Lamellen bleiben in JEDEM Alter rein weiss – Champignon-Lamellen sind jung rosa und werden alt schokoladenbraun bis schwarzbraun (nie dauerhaft weiss).$x9$,$x9$Am Stielgrund eine knollig verdickte Basis mit haeutiger, lappiger weisser Scheide (Volva/Eihuelle) – Champignons haben NIE eine Volva.$x9$,$x9$Sporenpulver weiss; Champignon-Sporenpulver ist braun.$x9$,$x9$Wuchs meist im (Nadel-)Wald, oft bei Fichten – Champignons bevorzugen Wiesen, Weiden und Kulturland.$x9$]::text[],$x9$Amanita virosa: rein weisser, oft kegeliger Hut, Lamellen bleiben weiss, knollige Stielbasis mit lappiger weisser Volva. Champignon: Lamellen rosa bis braun, keine Volva, Stielbasis nicht in haeutiger Scheide.$x9$,$x9$Amanita virosa unauffaellig bis suesslich-widerlich (verrottendes Fleisch). Champignon angenehm pilzig/nussig/anisartig.$x9$,$x9$Amanita virosa im Wald (oft Fichten/Nadelwald, saure Boeden); Champignons auf Wiesen, Weiden, Komposten, Kulturland.$x9$,$x9$Amanita virosa weiss, Champignon braun – Sporenabdruck ist ein zuverlaessiges Trennkriterium (weiss = Gefahr).$x9$,$x9$Pilz immer komplett samt Stielbasis aus dem Boden drehen und auf eine Volva (haeutige Scheide) am Knollengrund pruefen – Volva + weiss bleibende Lamellen + weisses Sporenpulver = toedlich, Finger weg. Bei Verdacht Tox Info Suisse 145 / VAPKO-Pilzkontrolle.$x9$,$x9$https://123pilzsuche.de/daten/details/KegelhuetigerKnollenblaetterpilz.htm · https://de.wikipedia.org/wiki/Kegelh%C3%BCtiger_Knollenbl%C3%A4tterpilz · https://www.toxinfo.ch/customer/files/930/MB-Amanita-D-2024.pdf · https://vapko.ch/phocadownload/public/TOUS/Giftpilzliste-Listedeschampignonstoxiques-plusmortels-2022.pdf$x9$),
($x9$champignon-de-paris$x9$,$x9$amanita_phalloides$x9$,$x9$sehr_hoch_lebensgefahr$x9$,array[$x9$Lamellen stets rein weiss (auch beim Altpilz) – Champignon-Lamellen sind jung rosa, alt braun/schwarzbraun.$x9$,$x9$Stielgrund mit knolliger, von einer haeutigen lappigen weissen Scheide (Volva) umgebener Basis – beim Champignon fehlt die Volva voellig.$x9$,$x9$Sporenpulver weiss (Champignon braun).$x9$,$x9$Junge Exemplare gleichen einem weissen 'Ei' und werden besonders leicht mit jungen geschlossenen Champignons verwechselt – immer aufschneiden, im Schnitt zeigt sich die angelegte weisse Lamellen-/Volvastruktur (innen einheitlich weiss-gruen, nie rosa).$x9$]::text[],$x9$Amanita phalloides: weiss bleibende Lamellen, haeutige weisse Volva am knolligen Stielgrund, Hut oliv-gruen bis (var. alba/jung) weiss. Champignon: rosa-braune Lamellen, keine Volva, Stielbasis ohne Scheide.$x9$,$x9$Amanita phalloides jung unauffaellig, alt modrig-suesslich nach Kunsthonig bis unangenehm. Champignon angenehm pilzig/nussig/anisartig.$x9$,$x9$Amanita phalloides als Mykorrhiza-Pilz im Laubwald (v.a. bei Eiche, Buche); Champignons auf offenem Kulturland, Wiesen und Weiden.$x9$,$x9$Amanita phalloides weiss, Champignon braun – weisser Sporenabdruck ist ein klares Warnsignal.$x9$,$x9$Verdaechtigen weissen Knopf/Ei laengs halbieren: Anlage von weissen Lamellen + Volva-Huelle am Grund = Knollenblaetterpilz, toedlich. Schon ca. 20 g sind lebensgefaehrlich – im Zweifel VAPKO-Pilzkontrolle / Tox Info Suisse 145.$x9$,$x9$https://de.wikipedia.org/wiki/Gr%C3%BCner_Knollenbl%C3%A4tterpilz · https://www.toxinfo.ch/customer/files/930/MB-Amanita-D-2024.pdf · https://www.awl.ch/pilze/vergleiche/champignon_vergleich/index.htm$x9$),
($x9$roetling$x9$,$x9$agaricus_xanthodermus$x9$,$x9$hoch$x9$,array[$x9$Geruch ist das wichtigste Merkmal: Schaf-Champignon angenehm nach Anis/Marzipan; Karbol-Champignon unangenehm nach Tinte/Karbol/Phenol - verstärkt beim Zerreiben der Stielbasis und beim Erhitzen.$x9$,$x9$Stielbasis längs anschneiden: Karbol-Champignon verfärbt sich SOFORT intensiv chromgelb, konzentriert am Stielgrund; Schaf-Champignon gilbt am ganzen Fruchtkörper nur schwach und nicht konzentriert am Stielgrund.$x9$,$x9$Beide haben Ring und Lamellen, die von blass-rosa zu schokobraun reifen, und beide haben dunkelbraunes Sporenpulver - daher trennen NUR Stielbasis-Schnitt (Chromgelb) UND Geruchstest sicher, nicht Lamellen oder Sporenfarbe.$x9$]::text[],$x9$Karbol-Champignon: Hut weiß bis kalkweiß, jung kugelig/halbkugelig, später abgeflacht, glatt bis feinschuppig; Stielbasis im Längsschnitt SOFORT leuchtend chromgelb. Schaf-Champignon: Hut cremeweiß, seidig-faserig bis leicht schuppig, gewölbt bis flach; gilbt am ganzen Pilz nur schwach und ohne den konzentrierten Chromgelb-Fleck am Stielgrund.$x9$,$x9$Entscheidendes Merkmal: Schaf-Champignon riecht angenehm nach Anis/Marzipan. Karbol-Champignon riecht unangenehm nach Tinte/Karbol/Phenol (medizinisch-jodig); der Geruch verstärkt sich beim Zerreiben der Stielbasis und besonders beim Erhitzen/Kochen.$x9$,$x9$Karbol-Champignon: Gärten, Parks, Waldränder, Komposthaufen, ruderale/siedlungsnahe Flächen. Schaf-Champignon: gedüngte Wiesen und Weiden, v.a. Schaf- und Pferdeweiden. Habitat allein trennt NICHT sicher (Überschneidung möglich).$x9$,$x9$Bei beiden Arten dunkel-schokobraun bis purpurbraun (Gattung Agaricus) - KEIN Trennmerkmal.$x9$,$x9$Stielbasis längs anschneiden: Färbt sie sich sofort intensiv chromgelb UND riecht der Pilz nach Tinte/Karbol statt nach Anis, liegen lassen - Karbol-Champignon. Faustregel: jeder Champignon mit Karbol-/Tintengeruch oder leuchtend chromgelber Stielbasis = giftig, nicht essen.$x9$,$x9$https://de.wikipedia.org/wiki/Karbol-Champignon · https://www.t-online.de/leben/essen-und-trinken/essen/id_65112638/anischampignon-achtung-verwechslungsgefahr-mit-giftpilzen.html · https://www.pilzbuch-pilzwelten.de/karbolchampignon/agaricus-xanthodermus.html · https://www.pilzbuch-pilzwelten.de/schafchampignon/agaricus-arvensis.html$x9$),
($x9$roetling$x9$,$x9$amanita_verna$x9$,$x9$sehr_hoch_lebensgefahr$x9$,array[$x9$Lamellen: Amanita verna hat in JEDEM Alter rein weiße Lamellen; Schaf-Champignon hat sie jung blass-rosa (sehr junge Knöpfe koennen creme-weiss sein!), später graurosa bis schokobraun. WICHTIG: Im Knopfstadium ist die Lamellenfarbe allein NICHT sicher - dann zwingend Volva + Sporenabwurf prüfen.$x9$,$x9$Stielbasis: Amanita verna hat eine deutlich abgesetzte Knolle mit häutiger, sackartiger Scheide (Volva); Champignon hat KEINE Volva. Stielbasis dazu immer komplett ausgraben - die Volva sitzt oft tief in der Erde.$x9$,$x9$Sporenpulver: Champignon dunkelbraun, Amanita verna rein WEISS - der Sporenabwurf ist das zuverlässigste Einzelmerkmal.$x9$,$x9$Geruch: Schaf-Champignon nach Anis; Amanita verna ohne Anisgeruch (neutral bis süßlich-honigartig) - fehlender Anisgeruch ist ein Warnsignal, ersetzt aber NIE die Volva-/Sporenprüfung.$x9$]::text[],$x9$Frühlings-Knollenblätterpilz: reinweißer Hut, REINWEISSE Lamellen (auch im Alter), Stielgrund mit knolliger, häutiger, sackartiger Scheide (Volva), oft tief in der Erde. Schaf-Champignon: cremeweißer Hut, Lamellen reifen rosa -> graurosa -> schokobraun, KEINE Volva, höchstens schwach verdickte Stielbasis.$x9$,$x9$Schaf-Champignon: angenehmer Anis-/Marzipangeruch. Amanita verna: nahezu geruchlos bis leicht süßlich/honigartig, im Alter unangenehm - KEIN Anis.$x9$,$x9$Amanita verna: Mykorrhizapilz, wächst im Wald (Laub-/Mischwald), v.a. im Frühjahr, mit Baumbindung. Schaf-Champignon: saprotroph auf offenen Wiesen und Weiden ohne Baumbindung. Achtung: Habitat allein ist KEIN sicheres Merkmal.$x9$,$x9$ENTSCHEIDEND und 100 % zuverlässig: Schaf-Champignon dunkel-schokobraun bis purpurbraun; Amanita verna REIN WEISS. Bei weißem Sporenabwurf NIEMALS als Champignon essen.$x9$,$x9$Bei jedem weißen 'Champignon' IMMER die Stielbasis vollständig ausgraben und freilegen: Findet sich eine knollige häutige Scheide (Volva) ODER bleiben die Lamellen rein weiß - lebensgefährlich, stehen lassen. Im Zweifel Sporenabwurf machen: weiß = Knollenblätterpilz, niemals essen. Junge, geschlossene weiße Knöpfe gar nicht erst sammeln.$x9$,$x9$https://de.wikipedia.org/wiki/Fr%C3%BChlings-Knollenbl%C3%A4tterpilz · https://www.t-online.de/leben/essen-und-trinken/essen/id_65112638/anischampignon-achtung-verwechslungsgefahr-mit-giftpilzen.html · https://www.pilzbuch-pilzwelten.de/schafchampignon/agaricus-arvensis.html · http://tintling.com/pilzbuch/arten/a/Amanita_verna.html$x9$),
($x9$roetling$x9$,$x9$amanita_phalloides$x9$,$x9$sehr_hoch_lebensgefahr$x9$,array[$x9$Lamellen: Grüner Knollenblätterpilz hat stets REINWEISSE Lamellen; Champignon-Lamellen sind jung blass-rosa (sehr junge Knöpfe ausnahmsweise creme-weiss) und reifen über graurosa zu schokobraun. Im Knopfstadium Lamellenfarbe nicht allein vertrauen - dann Volva + Sporenabwurf zwingend.$x9$,$x9$Stielbasis: deutlich abgesetzte Knolle mit häutiger Scheide (Volva) beim Knollenblätterpilz; beim Champignon fehlt die Volva. Stielbasis immer komplett ausgraben.$x9$,$x9$Hutfarbe NICHT als Hauptmerkmal verwenden: typisch oliv-/gelbgrün, aber als var. alba auch rein weiß - daher immer Lamellen + Volva + Sporenpulver prüfen, nie nur die Farbe.$x9$,$x9$Sporenpulver weiß (Champignon dunkelbraun) - zuverlässigstes Einzelmerkmal.$x9$]::text[],$x9$Grüner Knollenblätterpilz: Hut oliv-/gelbgrünlich mit eingewachsenen Radialfasern (weiße Form var. alba auch rein weiß), REINWEISSE Lamellen, knolliger Stielgrund mit häutiger Scheide (Volva). Schaf-Champignon: cremeweißer Hut, Lamellen rosa -> schokobraun, KEINE häutige Scheide.$x9$,$x9$Schaf-Champignon: angenehmer Anis-/Marzipangeruch. Grüner Knollenblätterpilz: jung süßlich-honigartig, im Alter unangenehm - KEIN Anis.$x9$,$x9$Amanita phalloides: Mykorrhizapilz vorwiegend bei Eichen und Buchen im Wald. Schaf-Champignon: freistehend auf Wiesen und Weiden ohne Baumbindung. Habitat allein ist KEIN sicheres Merkmal.$x9$,$x9$ENTSCHEIDEND: Schaf-Champignon dunkel-schokobraun bis purpurbraun; Amanita phalloides REIN WEISS. Weißer Sporenabwurf = niemals essen.$x9$,$x9$Niemals junge, noch geschlossene weiße 'Champignons' mit hellen Lamellen sammeln - genau im Knopfstadium sieht der tödliche Knollenblätterpilz dem Champignon am ähnlichsten. Stielbasis komplett ausgraben (Volva vorhanden?) und reinweiße Lamellen sowie weißen Sporenabwurf als absolutes Stopp-Signal werten.$x9$,$x9$https://de.wikipedia.org/wiki/Gr%C3%BCner_Knollenbl%C3%A4tterpilz · https://www.t-online.de/leben/essen-und-trinken/essen/id_65112638/anischampignon-achtung-verwechslungsgefahr-mit-giftpilzen.html · https://www.pilzbuch-pilzwelten.de/wiesenchampignon/agaricus-campestris.html · https://www.pilzbuch-pilzwelten.de/schafchampignon/agaricus-arvensis.html$x9$),
($x9$marasmius_oreades$x9$,$x9$clitocybe_rivulosa$x9$,$x9$hoch$x9$,array[$x9$Lamellen (DAS Hauptmerkmal): Gifttrichterling hat gedrängt stehende, am Stiel kurz HERABLAUFENDE (dekurrente) Lamellen — Nelkenschwindling hat ENTFERNT (weit) stehende, am Stiel ausgebuchtet angeheftete, NICHT herablaufende Lamellen$x9$,$x9$Stiel: Nelkenschwindling-Stiel zäh, biegsam, knorpelig-faserig (lässt sich verdrehen ohne zu brechen) — Trichterling-Stiel brüchig$x9$,$x9$Hut: Trichterling bleiweiss/cremegrau, hygrophan, oft niedergedrückt/trichterig — Nelkenschwindling lederbräunlich-gelb mit stumpfem Buckel$x9$,$x9$Reviving-Test: Nelkenschwindling-Fruchtkörper leben nach dem Trocknen wieder auf (typisch für Schwindlinge) — Gifttrichterling nicht$x9$]::text[],$x9$Nelkenschwindling: bräunlich-gelber Hut mit stumpfem Buckel, weit stehende blasse Lamellen, zäher biegsamer Stiel. Gifttrichterling: bleiweiss-cremegrauer, oft niedergedrückter/trichteriger Hut, gedrängte herablaufende Lamellen.$x9$,$x9$Nelkenschwindling: angenehm würzig nach Gewürznelken/Bittermandel (Blausäure-Note) — ACHTUNG: ~25% der Menschen können diesen Geruch genetisch bedingt NICHT wahrnehmen, daher kein Allein-Merkmal. Gifttrichterling: mehlig bis geruchlos. Geruch nur als Zusatz-Bestätigung, nie als alleinigen Sicherheitsbeweis nutzen.$x9$,$x9$Beide wachsen am SELBEN Standort: Wiesen, Weiden, Rasen in Gärten/Parks, beide bilden Hexenringe — keine Trennung über den Standort möglich. Das erhöht die Verwechslungsgefahr massiv.$x9$,$x9$Beide haben WEISSES Sporenpulver — Sporenabwurf trennt diese beiden NICHT. Entscheidend bleibt die Lamellenstellung (herablaufend vs. weit/ausgebuchtet) und der zähe Stiel.$x9$,$x9$Goldene Regel auf der Wiese: Lamellen prüfen. Nelkenschwindling hat WEIT auseinanderstehende, NICHT herablaufende Lamellen und einen zähen, biegsamen Stiel. Sind die Lamellen gedrängt und laufen am Stiel herab — stehen lassen (Verdacht auf muscarinhaltigen Gifttrichterling). Der würzige Nelkengeruch ist nur eine Zusatz-Bestätigung (ein Viertel der Menschen riecht ihn nicht).$x9$,$x9$https://en.wikipedia.org/wiki/Marasmius_oreades · https://en.wikipedia.org/wiki/Clitocybe_rivulosa · https://www.pilzbuch-pilzwelten.de/nelkenschwindling/marasmius-oreades.html · https://www.pilzkurse.com/nelkenschwindling/$x9$),
($x9$marasmius_oreades$x9$,$x9$clitocybe_dealbata$x9$,$x9$hoch$x9$,array[$x9$Lamellen: Feldtrichterling gedrängt, am Stiel angewachsen bis kurz HERABLAUFEND — Nelkenschwindling weit entfernt stehend, ausgebuchtet angeheftet, NICHT herablaufend$x9$,$x9$Hut: Feldtrichterling kreidig-bleiweiss bis cremegelb, glatt/bereift, flach bis niedergedrückt — Nelkenschwindling lederfarben mit stumpfem Buckel, hygrophan$x9$,$x9$Stiel: Nelkenschwindling zäh-biegsam, knorpelig-faserig — Feldtrichterling faseriger und brüchiger$x9$,$x9$Reviving-Test: Nelkenschwindling lebt nach Trocknung wieder auf — Feldtrichterling nicht$x9$]::text[],$x9$Feldtrichterling: kleiner, kreidig-bleiweisser bis cremegelber, oft niedergedrückter Hut mit gedrängten herablaufenden Lamellen. Nelkenschwindling: lederbraun-gelber Hut mit Buckel, weit stehende Lamellen, deutlich zäherer Stiel.$x9$,$x9$Nelkenschwindling angenehm würzig (Gewürznelke/Bittermandel) — von ~25% genetisch nicht wahrnehmbar, daher kein Allein-Merkmal. Feldtrichterling mehlig bis geruchlos.$x9$,$x9$Wie C. rivulosa ein typischer Wiesen-/Rasenpilz an grasbewachsenen Stellen, ggf. in Hexenringen — exakt im Lebensraum des Nelkenschwindlings. Standort taugt nicht zur Unterscheidung.$x9$,$x9$Beide mit WEISSEM Sporenpulver — kein Trennmerkmal. Entscheidend bleiben Lamellenstellung und der zähe Stiel.$x9$,$x9$Muscarin wirkt schon in kleinen Mengen (Schweiss-, Speichel-, Tränenfluss nach 15-30 Min). Nie sammeln, wenn die Lamellen gedrängt am Stiel herablaufen — der essbare Nelkenschwindling hat IMMER weit stehende, nicht herablaufende Lamellen und einen zähen, biegsamen Stiel. Der Nelkengeruch ist nur eine Zusatz-Bestätigung.$x9$,$x9$https://en.wikipedia.org/wiki/Marasmius_oreades · https://en.wikipedia.org/wiki/Clitocybe_dealbata · https://www.pilzbuch-pilzwelten.de/nelkenschwindling/marasmius-oreades.html$x9$),
($x9$marasmius_oreades$x9$,$x9$inocybe_erubescens$x9$,$x9$sehr_hoch_lebensgefahr$x9$,array[$x9$Sporenpulver (ENTSCHEIDEND): Risspilz hat DUNKELBRAUNES Sporenpulver, Lamellen verfärben sich von weiss/creme über olivgrau-rosa zu fleckig-bräunlich — Nelkenschwindling hat WEISSES Sporenpulver und bleibend blasse Lamellen$x9$,$x9$Rötung: Risspilz rötet ziegelrot (Hut/Stiel/Fleisch, v.a. auf Druck und im Alter) — Nelkenschwindling rötet NICHT$x9$,$x9$Hut-Oberfläche: Risspilz kegelig-gebuckelt, radialfaserig und aufreissend/rissig ('Risspilz') — Nelkenschwindling glatt, hygrophan, mit stumpfem Buckel$x9$,$x9$Geruch: Risspilz spermatisch/obstartig-unangenehm — Nelkenschwindling würzig nach Gewürznelken/Bittermandel$x9$]::text[],$x9$Risspilz: kegelig gebuckelter, radial aufgerissener Hut, weisslich und mit Zeit/Druck ziegelrot anlaufend, dunkelnde (olivrosa-bräunliche) Lamellen. Nelkenschwindling: glatter lederfarbener Hut mit stumpfem Buckel, blass bleibende weit stehende Lamellen.$x9$,$x9$Nelkenschwindling angenehm würzig (Gewürznelke/Bittermandel; von ~25% nicht wahrnehmbar). Ziegelroter Risspilz schwach obstartig, im Alter unangenehm süsslich-spermatisch. Geruch nur als Zusatz, nie allein.$x9$,$x9$Ziegelroter Risspilz wächst kalkliebend vor allem in Laub-/Mischwäldern, Parkanlagen und unter Gebüsch (Mykorrhiza mit Buche/Linde), teils auch auf Rasenflächen — nicht primär offene Wiese wie der Nelkenschwindling. Standort hilft, ist aber KEIN alleiniges Sicherheitsmerkmal (auch auf Rasen/Parkrasen möglich).$x9$,$x9$ENTSCHEIDEND und lebensrettend: Risspilz hat dunkelbraunes Sporenpulver — der Nelkenschwindling weisses. Ein Sporenabwurf trennt die beiden eindeutig.$x9$,$x9$Sporenpulver-Check als Lebensretter: weiss = Nelkenschwindling möglich, braun = NIE essen. Zusätzlich entlarven den tödlichen Risspilz: rissig-radialfaseriger Hut, ziegelrotes Anlaufen (auf Druck) und der spermatische Geruch. Muscarin — tödliche Menge schon ab ~40-500g Frischpilz.$x9$,$x9$https://de.wikipedia.org/wiki/Inocybe_erubescens · https://www.pilzbuch-pilzwelten.de/ziegelroter-risspilz/inosperma-erubescens.html · https://fundkorb.de/pilze/inocybe-erubescens-ziegelroter-risspilz$x9$),
($x9$infundibulicybe_geotropa$x9$,$x9$clitocybe_dealbata$x9$,$x9$hoch$x9$,array[$x9$Grösse/Fleisch: Feldtrichterling nur 2-5 cm Hut, dünnfleischig (wenige mm); Mönchskopf 12-25 cm, dick-fleischig und mit deutlich fühlbarem zentralem Buckel/Warze in der Hutmitte (Fingertest) - der Buckel fehlt dem Feldtrichterling immer.$x9$,$x9$Beide weiss/cremefarben & trichterig mit herablaufenden Lamellen und WEISSEM Sporenpulver - die Hutfarbe und das Sporenpulver helfen NICHT, nur Grösse + Fleischdicke + Buckel + Standort trennen sicher.$x9$,$x9$Standort/Saison: Feldtrichterling auf Wiesen, Weiden, Wegrändern, Rasen, Parks (Frühsommer-Spätherbst, oft in Hexenringen); Mönchskopf in Laub-/Nadelwald, an Waldrändern und auf Waldwiesen auf feuchtem Kalkboden (Spätsommer-Herbst, ebenfalls Hexenringe - Standort allein reicht NICHT).$x9$,$x9$Stiel: Mönchskopf hat kräftigen, oft keulig verdickten Stiel (2-4 cm dick, 8-15 cm lang); Feldtrichterling zierlich und dünn.$x9$]::text[],$x9$Mönchskopf: 12-25 cm, creme/lederfarben bis rötlich-ocker im Alter, zentraler fühlbarer Buckel, kräftig-keuliger Stiel. Feldtrichterling: nur 2-5 cm, kreideweiss bereift, niedergedrückt/eben ohne Buckel, dünner zierlicher Stiel.$x9$,$x9$Mönchskopf riecht aromatisch süsslich mit deutlicher Bittermandel-Note; Feldtrichterling unbedeutend bis schwach mehlig. Achtung: Geruch ist ein UNTERSTÜTZENDES Merkmal, niemals das alleinige Sicherheitskriterium - immer mit Grösse/Buckel/Fleischdicke kombinieren.$x9$,$x9$Feldtrichterling: offenes Grasland, Wiesen, Weiden, Rasen, Wegränder, Parks. Mönchskopf: Laub- und Nadelwald, Waldränder, Waldwiesen auf feuchtem Kalkboden. Beide können Hexenringe bilden - der Standort-Typ (Wald vs. offenes Gras) ist relevanter als das Ringe-Wachstum.$x9$,$x9$Beide WEISS - das Sporenpulver hilft hier NICHT zur Unterscheidung. Trennung erfolgt über Grösse, Fleischdicke, Hutbuckel und Stieldicke.$x9$,$x9$Goldene Regel: KLEINE weisse Trichterlinge (unter ca. 6 cm, dünnfleischig, ohne fühlbaren Hutbuckel) NIE essen - sie enthalten Muscarin und sind als Gruppe lebensgefährlich verwechselbar. Nur den grossen (12-25 cm), dick-fleischigen Mönchskopf mit eindeutig fühlbarem zentralem Hutbuckel und kräftigem Stiel nehmen. Hexenringe und weisses Sporenpulver haben BEIDE - sie taugen NICHT zur Unterscheidung.$x9$,$x9$https://de.wikipedia.org/wiki/M%C3%B6nchskopf · https://de.wikipedia.org/wiki/Feldtrichterling · https://www.pilzfinder.de/pilz/moenchskopf.html · https://naturlexikon-bayern.de/lexikon/pflanzen/pilze/moenchskopf/ · https://123pilzsuche.de/daten/details/MoenchskopfEssbar1004.htm$x9$)
